function LangButton({ lang, toggle }: { lang: Lang; toggle: (l: Lang) => void }) {
  return <div data-testid="button-language" role="group" className="lang-toggle" aria-label="Language">{LANGS.map((l,i)=><span key={l} style={{display:"contents"}}>{i>0&&<i/>}<span role="button" tabIndex={0} data-testid={`button-lang-${l}`} aria-pressed={lang===l} className={lang===l?"selected":""} onClick={()=>toggle(l)} onKeyDown={e=>{if(e.key==="Enter")toggle(l)}}>{l.toUpperCase()}</span></span>)}</div>;
}
function Brand() { return <Link href="/" className="brand" data-testid="link-home"><img src={`${basePath}/edutop-logo-cropped.png`} alt="EduTop — O‘zingizga mos kursni toping" /></Link>; }
