function Empty({title,detail}:{title:string;detail:string}) { return <div className="state-box"><div className="empty-mark"><BookOpen size={23}/></div><strong>{title}</strong><p>{detail}</p></div>; }
function CourseVideoPlayer({src,poster,lang}:{src:string;poster?:string|null;lang:Lang}){
  const [failed,setFailed]=useState(false);
  return <section className="detail-block course-video" data-testid="section-course-video"><h2>{tr('Kurs videosi','Видео курса',lang)}</h2>{failed?<p className="form-error" role="alert">{tr('Videoni yuklab bo‘lmadi. Keyinroq qayta urinib ko‘ring.','Не удалось загрузить видео. Попробуйте позже.',lang)}</p>:<video src={src} poster={poster||undefined} controls playsInline preload="metadata" aria-label={tr('Kurs videosi','Видео курса',lang)} onError={()=>setFailed(true)} style={{width:'100%',borderRadius:12,background:'#10202f',maxHeight:480}} data-testid="video-course"/>}</section>;
}
function RatingNote({lang}:{lang:Lang}){return <p className="subtle rating-note" data-testid="text-rating-note">{tr('Reyting — foydalanuvchilarning 1–5 baholari o‘rtachasi. Yuklangan sertifikatlarni o‘qituvchining o‘zi taqdim etadi, ular mustaqil tekshirilmaydi va yulduzlarni oshirmaydi.','Рейтинг — среднее пользовательских оценок от 1 до 5. Загруженные сертификаты предоставляет сам преподаватель, они не проверяются независимо и не повышают звёзды.',lang)}</p>}
function PriceView({c}:{c:Course}){
  if(c.priceType==='free'||c.priceUzs===0)return <strong className="price-free" data-testid="badge-free">{money(0)}</strong>;
  if(c.priceType==='discounted'&&c.originalPriceUzs)return <span className="price-stack"><del>{money(c.originalPriceUzs)}</del>{!!c.discountPercent&&<span className="discount-badge">-{c.discountPercent}%</span>}<strong>{money(c.priceUzs)}</strong></span>;
  return <strong>{money(c.priceUzs)}</strong>;
}
function CourseCard({course,lang}:{course:Course;lang:Lang}) {
  return <Link href={`/courses/${course.id}`} className="course-card" data-testid={`card-course-${course.id}`}>
    <div className="course-image">{course.imageUrl ? <img src={course.imageUrl} alt="" /> : <div className="image-placeholder"><span>{tr('Yangi bilimlar sari','К новым знаниям',lang)}</span><GraduationCap size={44}/></div>}
      {course.featured&&<span className="featured-badge"><Sparkles size={13}/>{tr('Tavsiya','Рекомендуем',lang)}</span>}
      <span className="delivery-pill">{course.deliveryMode==='online'?tr('Onlayn','Онлайн',lang):course.deliveryMode==='hybrid'?tr('Aralash','Гибрид',lang):tr('Oflayn','Офлайн',lang)}</span>
    </div><div className="course-card-body"><div className="course-meta"><span>{L(lang,course.teacher.cityUz,course.teacher.cityRu)}</span><span className="rating"><Star size={14} fill="currentColor"/>{course.ratingCount?<>{course.rating?.toFixed(1)}/5 <small>({course.ratingCount})</small></>:<small>{tr('Sharh yo‘q','Нет отзывов',lang)}</small>}</span></div>
    <h3>{L(lang,course.titleUz,course.titleRu)}</h3><p className="teacher-line">{course.teacher.verified&&<BadgeCheck size={15}/>} {L(lang,course.teacher.fullNameUz,course.teacher.fullNameRu)}</p><div className="course-card-bottom"><PriceView c={course}/><span>{tr('Batafsil','Подробнее',lang)} <ArrowRight size={15}/></span></div></div>
  </Link>;
}
